-- PT107-S3-Q21. Batch 03.
BEGIN;
DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch03$PT107-S3-Q21$batch03$ AND q.stimulus=$batch03$A study of the difference in earnings between men and women in the country of Naota found that the average annual earnings of women who are employed full time is 80 percent of the average annual earnings of men who are employed full time. However, other research consistently shows that, in Naota, the average annual earnings of all employed women is 65 percent of the average annual earnings of all employed men,$batch03$ AND q.prompt=$batch03$Which one of the following, if also established by research, most helps explain the apparent discrepancy between the research results described above?$batch03$ AND q.correct_choice=$batch03$D$batch03$) THEN RAISE EXCEPTION 'Question changed: PT107-S3-Q21'; END IF; END $guard$;
DO $guard$ BEGIN IF (SELECT COUNT(*) FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id WHERE q.qid=$batch03$PT107-S3-Q21$batch03$ AND e.style IN ('single','standard')) <> 0 THEN RAISE EXCEPTION 'Explanation row changed: PT107-S3-Q21'; END IF; END $guard$;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch03$PT107-S3-Q21$batch03$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch03$Given that$batch03$, $batch03$Among full-time workers, women's average earnings are 80 percent of men's.$batch03$), (1, $batch03$How can it be that$batch03$, $batch03$Among all workers, women's average earnings are only 65 percent of men's?$batch03$), (2, $batch03$Evaluate$batch03$, $batch03$The second figure includes part-time workers; the first does not. Put numbers on it. Say full-time men average $50,000 and full-time women $40,000 (80 percent). If many more women than men work part time at low pay, adding the part-timers drags the women's average down much more than the men's. The gap widens from 80 to 65.$batch03$), (3, $batch03$Goal$batch03$, $batch03$Find a difference between men and women in the group the first study left out: part-time workers.$batch03$)) v(position,label,body) WHERE q.qid=$batch03$PT107-S3-Q21$batch03$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch03$A$batch03$, $batch03$A gap that has grown over 30 years does not explain why two measurements taken now give different numbers.$batch03$), ($batch03$B$batch03$, $batch03$Women in identical jobs earning about the same as men is about full-time pay. It does not explain why including all workers lowers the ratio.$batch03$), ($batch03$C$batch03$, $batch03$More women in well-paid full-time jobs would raise women's averages. That works against a lower all-worker figure.$batch03$), ($batch03$D$batch03$, $batch03$A larger share of women work part time, and part-timers earn less. Adding them pulls the women's overall average down more than the men's, which turns 80 percent into 65.$batch03$), ($batch03$E$batch03$, $batch03$Figures from other countries cannot explain the gap between two figures about Naota.$batch03$)) v(letter,body) WHERE q.qid=$batch03$PT107-S3-Q21$batch03$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
